using System.Runtime.CompilerServices;
using System.Text.Json;
using CardGame.Content.Standard;
using CardGame.Core.Campaigns;
namespace CardGame.Core.Tests;
internal static class MouJiaXuAnniversaryChecks
{
 private const string Hero="mou:jia-xu",Quiet="fixture:mjx-anniv-quiet",Ally="fixture:mjx-anniv-ally",Actor="fixture:mjx-anniv-actor",Holder="fixture:mjx-anniv-holder",Deck="fixture:mjx-anniv-deck";
 public static void PrivateFumouNativeQueueAndRecordedRushiCold()
 {
  var registry=ContentRegistry.Build(new StandardContentPackage(),new Fixture());
  var setup=new ShanheBattleSetup(7,1,"mou-jia-xu-anniversary-native",Hero,20,17,0,0,0,[],[new(CardKind.Peach,Suit.Heart,5),new(CardKind.IronChain,Suit.Club,6)],[],
   [new(Actor,Hp:20){StartingHand=[new(CardKind.Slash,Suit.Spade,8),new(CardKind.DrawTwo,Suit.Heart,9),new(CardKind.Crossbow,Suit.Club,10),new(CardKind.Dodge,Suit.Club,2),new(CardKind.Dodge,Suit.Club,3)]},new(Holder,Hp:20){StartingHand=Enumerable.Range(0,6).Select(_=>new ShanheStartingCard(CardKind.Dodge,Suit.Club,4)).ToArray()}],
   [new(Ally,Hp:20){StartingHand=[]}],new string('a',64));
  var game=GameEngine.CreateStandard(new(){Seed=setup.BattleSeed,PlayerCount=4,HumanSeat=0,HumanRole=null,HumanTeamId=ShanheBattleSetup.PlayerTeamId,ModeId=ShanheBattleSetup.BattleModeId,ShanheBattle=setup,UseInteractiveSetup=false,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=9},registry);
  PendingDecision? Prompt()=>Enumerable.Range(0,4).Select(s=>game.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
  T[] Events<T>()=>game.Events.Select(e=>e.Payload).OfType<T>().ToArray();
  PlayerSnapshot Player(int seat)=>game.CreateSnapshot(0).Players[seat];
  MouJiaXuReceipt? Receipt()=>game.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(f=>f.MouJiaXu is not null)?.MouJiaXu;
  string Diagnostic()=>JsonSerializer.Serialize(new{game.State.TurnNumber,game.State.CurrentSeat,game.State.Phase,Prompt=Prompt(),Receipt=Receipt(),Players=game.CreateSnapshot(0).Players.Select(p=>new{p.Seat,p.GeneralId,p.Hp,p.HandCount,p.Equipment}),Frames=game.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Facts=game.Events.TakeLast(30).Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType()))});
  void Need(bool ok,string why){if(!ok)throw new InvalidOperationException(why+Diagnostic());}
  void Submit(GameCommand c){try{var result=game.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(result.Accepted,result.Error?.Message??"Native command rejected.");}catch(Exception e){throw new InvalidOperationException(e.Message+Diagnostic(),e);}}
  void Answer(Func<PromptChoice,bool> match){var p=Prompt();Need(p?.PlayerSeat==0,"Only the real published Human chooser answers.");var c=p!.Choices.FirstOrDefault(match);Need(c is not null,"The exact native choice is published.");Submit(new AnswerPromptCommand(0,p.PromptId,c!.Id,game.Revision));}
  void Reach(Func<bool> done,[CallerLineNumber]int line=0){for(var i=0;i<160;i++){if(done())return;Need(game.State.Winner==Winner.None,"Unexpected terminal result at "+line);if(Prompt()is{PlayerSeat:0})throw new InvalidOperationException("Unexpected actual Human boundary at "+line+Diagnostic());Submit(new AdvanceOneStepCommand(game.Revision));}throw new InvalidOperationException("Bounded native Jia Xu flow not reached at "+line+Diagnostic());}
  void Play()=>Reach(()=>Prompt()is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
  void Activate(string skill,string action)=>Submit(new UseProgramSkillCommand(0,skill,action,[],[],game.Revision,Prompt()!.PromptId));
  void Fumou(int holder){Activate("mou:fumou","view-show-and-use");Reach(()=>Receipt()?.Stage==MouJiaXuStage.Target&&Prompt()?.PlayerSeat==0);Answer(c=>c.Targets.SequenceEqual([holder]));Reach(()=>Receipt()?.Stage==MouJiaXuStage.Show&&Prompt()?.PlayerSeat==0);}
  void Add(int card)=>Answer(c=>c.Parameters.GetValueOrDefault("branch")=="add"&&c.Cards.SequenceEqual([card]));
  Submit(new StartGameCommand());Reach(()=>Receipt()?.Stage==MouJiaXuStage.Initial&&Prompt()?.PlayerSeat==0);Answer(c=>c.Parameters.GetValueOrDefault("branch")=="yin");Play();
  Need(Player(0).GeneralId==Hero&&Player(0).Hp==20&&Player(0).MaxHp==20&&Player(2).GeneralId==Actor&&Player(2).HandCount==5&&Player(0).Skills?.Any(s=>s.ContentId=="mou:rushi")!=true&&game.GetCombatDistance(2,0)==2&&game.GetAttackRange(2)==1,"The fixed actual roster starts with only Sushen/Fumou, real mixed opposing Hand and an out-of-range owner.");
  Fumou(2);var view=Receipt()!.View.ToArray();
  Need(view.Length==5&&game.CreateSnapshot(0).PrivateRevealedCards?.Select(c=>c.Id).Order().SequenceEqual(view.Select(c=>c.Id).Order())==true&&(game.CreateSnapshot(1).PrivateRevealedCards?.Count??0)==0,"Fumou privately shows the complete real other Hand to its owner before publishing only selected entities.");
  var shown=new[]{CardKind.Slash,CardKind.DrawTwo,CardKind.Crossbow}.Select(kind=>view.Single(c=>c.Kind==kind).Id).ToArray();foreach(var id in shown)Add(id);Answer(c=>c.Parameters.GetValueOrDefault("branch")=="done");
  Reach(()=>Receipt()is{Stage:MouJiaXuStage.Use,Yin:true,Holder:2}&&Prompt()?.PlayerSeat==2);
  Need(Receipt()!.Frozen.SequenceEqual(shown)&&Prompt()!.Choices.First().Cards.SequenceEqual([shown[0]])&&Prompt()!.Choices.First().Targets.SequenceEqual([0])&&game.GetCombatDistance(2,0)>game.GetAttackRange(2)&&Player(0).Hand.Any(c=>c.Kind==CardKind.Dodge),"The actual holder's first genuine native Slash request reaches the distant owner while the owner really has Dodge; only the own issued request grants distance and no-response.");
  Play();var issued=Events<MouJiaXuUseIssuedEvent>().ToArray();
  Need(issued.Length==3&&issued.Select(e=>e.CardId).Order().SequenceEqual(shown.Order())&&issued.All(e=>e.Actor==2&&Events<MouJiaXuUseReturnedEvent>().Count(r=>r.UseId==e.UseId&&r.ActionId==e.ActionId)==1&&Events<CardUseFinishedEvent>().Count(f=>f.ResolutionId==e.UseId&&f.CardId==e.CardId)==1&&Events<IssuedCardNoResponseEvent>().Any(p=>p.Effect.ParentFrameId==e.UseId&&p.Effect.CardActionId==e.ActionId))&&issued.All(e=>Events<CardUseAppearanceCapturedEvent>().Any(p=>p.Action.ActionId==e.ActionId&&p.Action.Type==CardActionType.Use&&p.Action.ActorSeat==2&&p.Action.ProviderSeat==2&&p.Action.PhysicalCards is[{CardId:var material,From:var from}]&&material==e.CardId&&from==CardLocation.Hand(2)))&&Player(0).Hp==19&&Player(2).Equipment.Any(c=>c.Id==shown[2])&&Events<DamageAppliedEvent>().Any(e=>e.SourceSeat==2&&e.TargetSeat==0&&e.Amount==1),"The shown Slash, DrawTwo and Equipment each pay the actual holder's own entity, finish and return once through full native effects; the genuine unrespondable distant Slash damages the owner without a fabricated response or damage shortcut.");
  var recordHand=Player(0).HandCount;Activate("mou:sushen","record-and-enter");Play();var recorded=Events<MouJiaXuRecordedEvent>().Single();
  Need(recorded.Hp==19&&recorded.HandCount==recordHand&&!recorded.Yin&&Events<MouJiaXuDerivedGrantedEvent>()is[{Owner:0}]&&Player(0).Skills?.Any(s=>s.ContentId=="mou:rushi")==true&&game.GetHumanLegalActions().Any(a=>a.ProgramSkillId=="mou:rushi")&&!game.GetHumanLegalActions().Any(a=>a.ProgramSkillId=="mou:sushen"),"Sushen records actual current HP, Hand count and converted Yang state before truly granting derived Rushi, with its own limited use spent.");
  var peach=Player(0).Hand.Single(c=>c.Kind==CardKind.Peach).Id;var peachAction=game.GetHumanLegalActions().FirstOrDefault(a=>a.CardId==peach&&a.ConversionSource is null);Need(peachAction is not null,"The actual lost HP permits a true physical Peach.");Submit(new PlayCardCommand(0,peach,peachAction!.TargetSeats,game.Revision,Prompt()!.PromptId,peachAction.PlayedCardKind,peachAction.TargetCardId));Play();Need(Player(0).Hp==20,"A genuine native Peach changes HP after the record.");
  var firstTurn=game.State.TurnNumber;Submit(new EndPlayPhaseCommand(0,game.Revision,Prompt()!.PromptId));Play();Need(Events<TurnEndedEvent>().Any(e=>e.ActorSeat==0&&e.TurnNumber==firstTurn),"The Yang branch starts in another real actual Play phase.");
  var sourceHand=Player(3).HandCount;var ownerHand=Player(0).HandCount;Fumou(3);Need(Receipt()is{Yin:false},"The native conversion state selects Yang after the completed prior Yin.");var transferred=Receipt()!.View.Take(2).Select(c=>c.Id).ToArray();foreach(var id in transferred)Add(id);Answer(c=>c.Parameters.GetValueOrDefault("branch")=="done");Reach(()=>Receipt()?.Stage==MouJiaXuStage.Recipient&&Prompt()?.PlayerSeat==0);Answer(c=>c.Targets.SequenceEqual([1]));Play();
  Need(Events<MouJiaXuTransferredEvent>().Select(e=>e.CardId).Order().SequenceEqual(transferred.Order())&&transferred.All(id=>game.CardMovements.Count(m=>m.CardId==id&&m.From==CardLocation.Hand(3)&&m.To==CardLocation.Hand(1))==1)&&Events<MouJiaXuDrawReturnedEvent>().Select(e=>(e.Recipient,e.Requested,e.Actual)).SequenceEqual([(0,2,2),(3,2,2)])&&Player(3).HandCount==sourceHand&&Player(0).HandCount==ownerHand+2,"Yang obtains the exact shown entities into a distinct third Hand, then separately draws the frozen shown count for owner and original holder even when that holder's net Hand difference is zero.");
  Activate("mou:rushi","restore-recorded-values");Reach(()=>Receipt()?.Stage==MouJiaXuStage.Discard&&Prompt()?.PlayerSeat==0);
  Need(Player(0).Hp==recorded.Hp&&Events<MouJiaXuHpSetEvent>()is[{Before:20,After:19,RecordFrameId:var recordFrame,ChangeId:not null}]&&recordFrame==recorded.FrameId&&Receipt()!.Record==recorded,"Rushi first executes the true recorded HP Setting and its native children, retaining the same original scalar record before adjusting the current Hand.");
  var discardCount=Player(0).HandCount-recorded.HandCount;var costs=Player(0).Hand.Where(c=>c.Kind==CardKind.Dodge).Take(discardCount).Select(c=>c.Id).ToArray();Need(discardCount>1&&costs.Length==discardCount,"The real current Hand requires a nontrivial payable adjustment.");Add(costs[0]);
  var before=SnapshotJson.Serialize(game.CreateSnapshot(0));var otherBefore=SnapshotJson.Serialize(game.CreateSnapshot(3));game=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(game.CreateCheckpoint())),registry);
  Need(before==SnapshotJson.Serialize(game.CreateSnapshot(0))&&otherBefore==SnapshotJson.Serialize(game.CreateSnapshot(3))&&Receipt()is{Stage:MouJiaXuStage.Discard,Selected.Count:1}&&Receipt()!.Selected.SequenceEqual([costs[0]])&&Receipt()!.Record==recorded&&Events<MouJiaXuHpSetEvent>().Length==1&&Events<MouJiaXuDiscardPaidEvent>().Length==0,"One representative Cold preserves the private partial Hand payment and recorded source after the completed HP child, without repeating the already finished Setting or issuing unfinished discards.");
  foreach(var id in costs.Skip(1))Add(id);Answer(c=>c.Parameters.GetValueOrDefault("branch")=="done");Play();
  Need(Player(0).Hp==recorded.Hp&&Player(0).HandCount==recorded.HandCount&&Events<MouJiaXuHpSetEvent>().Length==1&&Events<MouJiaXuDiscardPaidEvent>().Select(e=>e.CardId).Order().SequenceEqual(costs.Order())&&costs.All(id=>game.CardMovements.Count(m=>m.CardId==id&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.DiscardPile)==1)&&Events<ProgramBooleanStateChangedEvent>().Last(e=>e.OwnerSeat==0&&e.SkillId=="mou:fumou"&&e.StateId=="yin").Value==recorded.Yin&&!game.GetHumanLegalActions().Any(a=>a.ProgramSkillId is"mou:sushen"or"mou:rushi"or"mou:fumou"),"Rushi pays only actual selected Hand entities once, restores the recorded scalar values and Yang state, and does not refund either limited skill or the current Play's already spent Fumou allowance.");
 }
 private sealed class Fixture:IGameContentPackage
 {
  public PackageManifest Manifest{get;}=new("fixture-mou-jia-xu-anniversary",new(1,0,0));
  public void Register(IContentRegistryBuilder b)
  {
   CharacterFixtureContent.Register(b,Hero);foreach(var kind in new[]{CardKind.Peach,CardKind.IronChain,CardKind.Slash,CardKind.DrawTwo,CardKind.Crossbow,CardKind.Dodge}){var c=CardCatalog.Get(kind);b.AddCard(new("fixture:mjx-anniv-"+kind,c.DisplayName,c.CategoryName,c.Description,kind));}
   var catalog=SkillProgramCatalog.Load($$"""
    {"schemaVersion":{{SkillProgramCatalog.RulesSchemaVersion}},"skills":[{"id":"{{Quiet}}","revision":1,"triggers":[{"id":"quiet","window":"afterNormalDraw","subject":"owner","optional":false,"effects":[{"op":"skipTurnPhases","target":"owner","phases":["play"]}]}]}]}
    """,JsonSerializer.Serialize(new{schemaVersion=SkillProgramCatalog.PresentationSchemaVersion,skills=new Dictionary<string,object>{[Quiet]=new{name="安静同行",description="正常摸牌后跳过出牌"}}}));b.AddSkill(new(Quiet,"安静同行","正常摸牌后跳过出牌"){Program=catalog.Programs[Quiet],ProgramPresentation=catalog.Presentations[Quiet]});foreach(var id in new[]{Ally,Actor,Holder})b.AddGeneral(new(id,"真实同行","supporter",Quiet,"wei",20));
   b.AddDeck(new(Deck,"固定真实闪牌堆",0,2,[]){PhysicalCards=Enumerable.Range(0,90).Select(_=>new ContentDeckPhysicalCard("fixture:mjx-anniv-"+CardKind.Dodge,Suit.Club,2)).ToArray()});b.AddMode(new(ShanheBattleSetup.BattleModeId,"谋贾诩十周年真实主流程",4,4,new Dictionary<string,int>(),Deck,GeneralPoolIds:[Hero,Ally,Actor,Holder],ModeKind:ContentModeKind.Team,TeamCounts:new Dictionary<string,int>{[ShanheBattleSetup.PlayerTeamId]=2,[ShanheBattleSetup.EnemyTeamId]=2}));
  }
 }
}
